     const slug = raw.toLowerCase().replace(/[^\w]+/g, '-')
-    return `<h${level} id="${slug}">${raw}<a href="#${slug}" class="anchor">#</a></h${level}>`
+    return `<h${level} id="${slug}">${text}<a href="#${slug}" class="anchor">#</a></h${level}>`
   }

But we need to confirm if the code uses `text` or something else.

Maybe the code uses `this.parser.parseInline(tokens)`? In marked v4+, the heading renderer receives tokens. The default implementation is:

heading(tokens, level, options, env, self) {
  const content = this.parser.parseInline(tokens, options, env, self)
  return `<h${level}>${content}</h${level}>\n`
}

If they override it, they might do:

heading(tokens, level, options, env, self) {
  const raw = tokens[0].content // or something
  const content = this.parser.parseInline(tokens, options, env, self)
  // but they might use raw for something
}

But the vulnerability might be that they use the raw token content for the heading text without parsing inline tokens, thus bypassing the html escaping.

For example:

renderer.heading = function (tokens, level) {
  const token = tokens[0]
  const content = token.content // raw content

