+package org.apache.streampipes.manager.extension.utils;
+
+import java.net.InetAddress;
+import java.net.URI;
+import java.util.Collections;
+import java.util.List;
+
+public class UrlValidationUtils {
+
+    /**
+     * Validates that a URL is a public HTTP/HTTPS endpoint, preventing SSRF attacks.
+     * Blocks non-HTTP(S) schemes, internal/private IPs, loopback, link-local, multicast, and IPv6 unique local addresses.
+     * Resolves all host IPs to prevent DNS rebinding attacks.
+     */
+    public static boolean isValidPublicUrl(String url) {
+        try {
+            URI uri = new URI(url);
+            // Only allow HTTP and HTTPS schemes
+            String scheme = uri.getScheme();
+            if (scheme == null || !(scheme.equalsIgnoreCase("http") || scheme.equalsIgnoreCase("https"))) {
+                return false;
+            }
+            String host = uri.getHost();
+            if (host == null || host.trim().isEmpty()) {
+                return false;
+            }
+            // Resolve all IP addresses for the host to prevent DNS rebinding
+            List<InetAddress> addresses = Collections.list(InetAddress.getAllByName(host));
+            for (InetAddress address : addresses) {
+                // Block internal, loopback, link-local, any, and multicast addresses
+                if (address.isLoopbackAddress() ||
+                        address.isSiteLocalAddress() ||
+                        address.isLinkLocalAddress() ||
+                        address.isAnyLocalAddress() ||
+                        address.isMulticastAddress()) {
+                    return false;
+                }
+                // Block IPv6 unique local addresses (fc00::/7)
+                if (address instanceof Inet6Address) {
+                    byte[] addrBytes = address.getAddress();
+                    if ((addrBytes[0] & 0xfe) == 0xfc) {
+                        return false;
+                    }
+                }
+            }
+            return true;
+        } catch (URISyntaxException | UnknownHostException e) {
+            return false;
+        }
+    }
+}

